import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { NarrativeMapResult, NarrativeNode, NarrativeLink, TimelineEvent } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import CloseIcon from './icons/CloseIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import UserIcon from './icons/UserIcon';
import GavelIcon from './icons/GavelIcon';
import GlobeIcon from './icons/GlobeIcon';
import DocumentIcon from './icons/DocumentIcon';
import AlertIcon from './icons/AlertIcon';
import CalendarIcon from './icons/CalendarIcon';
import DownloadIcon from './icons/DownloadIcon';
import ChevronDownIcon from './icons/ChevronDownIcon';

interface NarrativeMapperProps {
    onClose: () => void;
    onGenerate: (base64Content: string, mimeType: string, fileName: string) => Promise<NarrativeMapResult>;
    initialData?: { b64: string, mime: string, name: string } | null;
}

const getNodeIcon = (type: string, className = "w-5 h-5") => {
    switch (type) {
        case 'person': return <UserIcon className={className} />;
        case 'location': return <GlobeIcon className={className} />;
        case 'institution': return <GavelIcon className={className} />;
        case 'event': return <CalendarIcon className={className} />;
        default: return <DocumentIcon className={className} />;
    }
};

const getNodeColor = (type: string, isBrady: boolean) => {
    if (isBrady) return 'bg-red-900 border-red-500 text-white';
    return 'bg-[#050505] border-[#b5892f] text-[#e2c07d]';
};

const EvidenceBadge: React.FC<{ tag: string }> = ({ tag }) => {
    let borderColor = "#6e501a";
    let textColor = "#a0a0a0";
    if (tag.includes("Brady")) { borderColor = "#ef4444"; textColor = "#ef4444"; }
    else if (tag.includes("613")) { borderColor = "#b5892f"; textColor = "#e2c07d"; }
    return (
        <span className="px-2 py-0.5 rounded-[2px] text-[8px] font-black uppercase border tracking-tighter shadow-sm" style={{borderColor, color: textColor, backgroundColor: 'rgba(0,0,0,0.5)'}}>
            {tag}
        </span>
    );
};

const GraphView: React.FC<{ data: NarrativeMapResult; onNodeClick: (node: NarrativeNode) => void; activeNodeId: string | null; svgRef: React.RefObject<SVGSVGElement | null>; containerRef: React.RefObject<HTMLDivElement | null>; }> = ({ data, onNodeClick, activeNodeId, svgRef, containerRef }) => {
    const [positions, setPositions] = useState<Record<string, { x: number, y: number }>>({});
    const [draggingId, setDraggingId] = useState<string | null>(null);

    useEffect(() => {
        const width = 800; const height = 600; const newPos: Record<string, { x: number, y: number }> = {};
        const people = data.nodes.filter(n => n.type === 'person');
        const others = data.nodes.filter(n => n.type !== 'person');
        people.forEach((node, i) => { const angle = (i / people.length) * 2 * Math.PI; newPos[node.id] = { x: 400 + Math.cos(angle) * 150, y: 300 + Math.sin(angle) * 150 }; });
        others.forEach((node, i) => { const angle = (i / others.length) * 2 * Math.PI; newPos[node.id] = { x: 400 + Math.cos(angle) * 250, y: 300 + Math.sin(angle) * 250 }; });
        setPositions(newPos);
    }, [data]);

    return (
        <div ref={containerRef} className="bg-[#050505] rounded-none overflow-hidden relative h-full w-full border border-[#6e501a]/20">
            <div className="absolute inset-0 opacity-[0.05] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#b5892f 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
            <svg ref={svgRef} width="100%" height="100%" viewBox="0 0 800 600" onMouseMove={(e) => { if (draggingId) { const r = svgRef.current!.getBoundingClientRect(); setPositions(p => ({...p, [draggingId]: { x: (e.clientX - r.left) * (800/r.width), y: (e.clientY - r.top) * (600/r.height) }})); } }} onMouseUp={() => setDraggingId(null)} className="cursor-crosshair">
                <defs>
                    <marker id="arrow" markerWidth="10" markerHeight="10" refX="28" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#6e501a" /></marker>
                    <marker id="arrow-contradiction" markerWidth="10" markerHeight="10" refX="28" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#ef4444" /></marker>
                </defs>
                {data.links.map((l, i) => {
                    const s = positions[l.source], e = positions[l.target]; if (!s || !e) return null;
                    const isContradiction = l.type === 'contradiction';
                    const isInferred = l.type === 'inferred';
                    return (
                        <g key={i}>
                            <line 
                                x1={s.x} y1={s.y} x2={e.x} y2={e.y} 
                                stroke={isContradiction ? '#ef4444' : (isInferred ? '#6e501a' : '#b5892f')} 
                                strokeWidth={isContradiction ? "2" : "1"} 
                                strokeDasharray={isInferred ? "5,5" : "0"}
                                opacity="0.6" 
                                markerEnd={isContradiction ? "url(#arrow-contradiction)" : "url(#arrow)"} 
                            />
                            <foreignObject x={(s.x+e.x)/2 - 50} y={(s.y+e.y)/2 - 10} width="100" height="20">
                                <div className={`text-[8px] font-black text-center uppercase tracking-tighter ${isContradiction ? 'text-red-500' : 'text-[#6e501a]'}`}>{l.label}</div>
                            </foreignObject>
                        </g>
                    );
                })}
                {data.nodes.map(n => {
                    const p = positions[n.id]; if (!p) return null;
                    const isActive = activeNodeId === n.id;
                    const color = !!n.bradyFlag ? '#ef4444' : '#b5892f';
                    return (
                        <g key={n.id} transform={`translate(${p.x}, ${p.y})`} onClick={() => onNodeClick(n)} onMouseDown={() => setDraggingId(n.id)} className="cursor-pointer">
                            <circle r="24" fill="#050505" stroke={isActive ? '#e2c07d' : color} strokeWidth={isActive ? "3" : "1"} />
                            <foreignObject x="-12" y="-12" width="24" height="24"><div className="flex justify-center" style={{color: !!n.bradyFlag ? '#ef4444' : '#b5892f'}}>{getNodeIcon(n.type, "w-6 h-6")}</div></foreignObject>
                            <text y="42" fill="#efefef" fontSize="10" fontWeight="900" textAnchor="middle" className="uppercase tracking-widest">{n.label}</text>
                            {n.bradyFlag && <circle r="6" cx="18" cy="-18" fill="#ef4444" />}
                        </g>
                    );
                })}
            </svg>
        </div>
    );
};

export default function NarrativeMapper({ onClose, onGenerate, initialData }: NarrativeMapperProps): React.ReactNode {
    const [file, setFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<NarrativeMapResult | null>(null);
    const [selectedNode, setSelectedNode] = useState<NarrativeNode | null>(null);
    const [isExportMenuOpen, setIsExportMenuOpen] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);

    const handleGenerateInternal = useCallback(async (b64: string, mime: string, name: string) => {
        setIsLoading(true);
        try {
            const res = await onGenerate(b64, mime, name);
            setResult(res);
        } catch (e) {
            console.error("Mapping failure:", e);
        } finally {
            setIsLoading(false);
        }
    }, [onGenerate]);

    useEffect(() => {
        if (initialData) {
            handleGenerateInternal(initialData.b64, initialData.mime, initialData.name);
        }
    }, [initialData, handleGenerateInternal]);

    const handleManualGenerate = async () => {
        if (!file) return; 
        try {
            const b64 = await new Promise<string>((resolve, reject) => { 
                const rd = new FileReader(); 
                rd.onload = () => {
                    const res = rd.result as string;
                    if (res) resolve(res.split(',')[1]);
                    else reject(new Error("File read error"));
                }; 
                rd.onerror = () => reject(new Error("Dossier injection failed"));
                rd.readAsDataURL(file); 
            });
            await handleGenerateInternal(b64, file.type, file.name);
        } catch (e) {
            console.error("Manual mapping trigger error:", e);
        }
    };

    const handleExportPNG = async () => {
        if (!containerRef.current) return;
        setIsExporting(true);
        setIsExportMenuOpen(false);
        try {
            // @ts-ignore - html2canvas is globally available via script tag in index.html
            const canvas = await html2canvas(containerRef.current, {
                backgroundColor: '#050505',
                scale: 3, // Higher resolution
                useCORS: true,
                logging: false
            });
            const link = document.createElement('a');
            link.download = `NARRATIVE_MATRIX_${result?.nodes.length}_NODES.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        } catch (err) {
            console.error("PNG Export Failed", err);
            alert("Strategic Capture Failed: Analysis stream interrupted.");
        } finally {
            setIsExporting(false);
        }
    };

    const handleExportSVG = () => {
        if (!svgRef.current) return;
        setIsExportMenuOpen(false);
        try {
            const serializer = new XMLSerializer();
            let source = serializer.serializeToString(svgRef.current);
            if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
                source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
            }
            if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
                source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
            }
            source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
            const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
            const link = document.createElement('a');
            link.download = `NARRATIVE_MATRIX_${result?.nodes.length}_NODES.svg`;
            link.href = url;
            link.click();
        } catch (err) {
            console.error("SVG Export Failed", err);
        }
    };

    if (!result && !isLoading) {
        return (
            <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4">
                <div className="bg-[#121212] border border-[#6e501a] p-10 max-w-xl w-full text-center relative">
                    <div className="absolute top-0 left-0 right-0 h-1 bg-[#b5892f]"></div>
                    <h2 className="text-3xl font-black text-[#efefef] tracking-tighter uppercase italic mb-6">Narrative Matrix Generator</h2>
                    <input type="file" accept="application/pdf" onChange={(e) => e.target.files && setFile(e.target.files[0])} className="hidden" id="f-mapper" />
                    <label htmlFor="f-mapper" className="block p-12 border border-dashed border-[#6e501a]/40 mb-10 cursor-pointer hover:bg-[#b5892f]/5">
                        <DocumentIcon className="w-12 h-12 text-[#6e501a] mx-auto mb-4" />
                        <span className="text-xs font-black text-[#e2c07d] uppercase tracking-widest">{file ? file.name : "Inject Discovery Data"}</span>
                    </label>
                    <button onClick={handleManualGenerate} disabled={!file} className="w-full py-5 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-xl hover:bg-[#e2c07d] transition-all shadow-xl">Synchronise Narrative tracks</button>
                    <button onClick={onClose} className="mt-6 text-[#6e501a] text-[10px] font-black uppercase tracking-widest hover:text-[#efefef]">Abort Command</button>
                </div>
            </div>
        );
    }

    if (isLoading) return (
        <div className="fixed inset-0 bg-[#050505] flex flex-col items-center justify-center z-50">
            <SpinnerIcon className="w-16 h-16 text-[#b5892f] mb-8" />
            <div className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.6em] animate-pulse">Reconstructing Narrative Timeline...</div>
        </div>
    );

    return (
        <div className="fixed inset-0 bg-[#050505] z-50 flex flex-col animate-[fadeIn_0.3s_ease-out]">
            <div className="p-6 bg-[#121212] border-b border-[#6e501a]/30 flex justify-between items-center shadow-2xl z-50">
                <div className="flex items-center gap-6">
                    <BrainCircuitIcon className="w-8 h-8 text-[#b5892f]" />
                    <h2 className="text-2xl font-black text-[#efefef] uppercase italic tracking-tighter">Narrative Matrix: {initialData?.name || file?.name}</h2>
                </div>
                <div className="flex gap-4 relative">
                    <button 
                        onClick={() => setIsExportMenuOpen(!isExportMenuOpen)}
                        className="px-6 py-2 border border-[#6e501a] text-[#b5892f] text-[10px] font-black uppercase tracking-widest hover:bg-[#b5892f]/5 transition-all flex items-center gap-2"
                        disabled={isExporting}
                    >
                        {isExporting ? <SpinnerIcon className="w-3 h-3 animate-spin" /> : <DownloadIcon className="w-4 h-4" />}
                        {isExporting ? 'Capturing...' : 'Export Matrix'}
                        <ChevronDownIcon className={`w-3 h-3 transition-transform ${isExportMenuOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {isExportMenuOpen && (
                        <div className="absolute top-full right-0 mt-2 w-48 bg-[#121212] border border-[#6e501a] shadow-2xl flex flex-col z-[100]">
                            <button onClick={handleExportPNG} className="p-4 text-left text-[10px] font-black text-[#efefef] uppercase tracking-widest hover:bg-[#b5892f] hover:text-black transition-all">Capture High-Res PNG</button>
                            <button onClick={handleExportSVG} className="p-4 text-left text-[10px] font-black text-[#efefef] uppercase tracking-widest hover:bg-[#b5892f] hover:text-black transition-all border-t border-[#6e501a]/20">Download Raw SVG</button>
                        </div>
                    )}

                    <button onClick={onClose} className="text-[#6e501a] hover:text-[#efefef]"><CloseIcon className="w-6 h-6" /></button>
                </div>
            </div>

            <div className="flex-grow flex overflow-hidden">
                <div className="w-[30%] xl:w-[25%] border-r border-[#6e501a]/20 flex flex-col bg-[#121212]">
                    <div className="p-4 bg-[#050505] border-b border-[#6e501a]/20 text-[10px] font-black text-[#6e501a] uppercase tracking-widest flex items-center gap-3">
                        <CalendarIcon className="w-3 h-3" />
                        Chronological Vector Log
                    </div>
                    <div className="flex-grow overflow-y-auto p-6 space-y-8 custom-scrollbar">
                        {result?.timeline.map((e, i) => (
                            <div key={i} className={`p-4 border border-[#6e501a]/20 relative group hover:border-[#b5892f]/40 transition-all ${e.narrativeTrack === 'defense' ? 'bg-[#b5892f]/5 border-l-2 border-l-[#b5892f]' : 'bg-[#050505]'}`}>
                                <div className="flex justify-between text-[9px] font-black uppercase tracking-tighter mb-2">
                                    <span className="text-[#e2c07d]">{e.date}</span>
                                    <span className={`px-1 ${e.narrativeTrack === 'prosecution' ? 'text-red-500' : 'text-blue-400'}`}>{e.narrativeTrack}</span>
                                </div>
                                <p className="text-sm font-bold text-white leading-tight">{e.description}</p>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="flex-grow flex flex-col relative">
                    <GraphView 
                        data={result!} 
                        onNodeClick={setSelectedNode} 
                        activeNodeId={selectedNode?.id || null} 
                        svgRef={svgRef} 
                        containerRef={containerRef}
                    />
                    <div className="h-[35%] bg-[#121212] border-t border-[#6e501a] flex shadow-2xl z-20">
                        <div className="w-1/2 p-8 border-r border-[#6e501a]/10 overflow-y-auto custom-scrollbar">
                            <h3 className="text-[10px] font-black text-[#b5892f] uppercase tracking-[0.4em] mb-4">Strategic Assessment</h3>
                            <p className="text-lg text-white font-light italic leading-relaxed">"{result?.strategicAssessment}"</p>
                        </div>
                        <div className="w-1/2 p-8 overflow-y-auto bg-[#050505] custom-scrollbar">
                            {selectedNode ? (
                                <div className="animate-in fade-in slide-in-from-bottom-2 duration-300">
                                    <div className="flex items-center justify-between mb-6">
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-[#121212] border border-[#6e501a]/50 rounded-sm text-[#b5892f]">
                                                {getNodeIcon(selectedNode.type, "w-8 h-8")}
                                            </div>
                                            <div>
                                                <h4 className="text-xl font-black text-[#efefef] uppercase tracking-tighter italic">{selectedNode.label}</h4>
                                                <div className="text-[9px] font-black text-[#6e501a] uppercase tracking-[0.2em]">{selectedNode.type} profile</div>
                                            </div>
                                        </div>
                                        <div className="flex flex-wrap gap-2 justify-end">
                                            {selectedNode.evidenceTags?.map((t, i) => <EvidenceBadge key={i} tag={t} />)}
                                        </div>
                                    </div>
                                    <p className="text-sm text-slate-400 font-light mb-6 leading-relaxed">{selectedNode.description}</p>
                                    {selectedNode.sourceCitation && (
                                        <div className="p-4 bg-[#121212] border-l-2 border-[#b5892f]">
                                            <span className="text-[9px] font-black text-[#6e501a] uppercase block mb-1">Authenticated Citation</span>
                                            <p className="text-[10px] text-[#e2c07d] font-mono uppercase tracking-widest">{selectedNode.sourceCitation}</p>
                                        </div>
                                    )}
                                </div>
                            ) : (
                                <div className="h-full flex items-center justify-center text-[#6e501a] text-[10px] font-black uppercase tracking-widest italic opacity-20">Link to Neural Node to Inspect Evidence</div>
                            )}
                        </div>
                    </div>
                </div>
            </div>
            <style>{`
                @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #6e501a; }
            `}</style>
        </div>
    );
}

import React, { useState, useRef, useMemo } from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { type SearchResult, type SearchParams } from '../types';
import FollowUpQuestions from './FollowUpQuestions';
import BookmarkIcon from './icons/BookmarkIcon';
import BookmarkFilledIcon from './icons/BookmarkFilledIcon';
import DownloadIcon from './icons/DownloadIcon';
import RelatedQueries from './RelatedQueries';
import GlobeIcon from './icons/GlobeIcon';
import TimelineChart from './TimelineChart';
import IdentifiedJudges from './IdentifiedJudges';
import AdversarialStrategyWidget from './AdversarialStrategyWidget';
import SpinnerIcon from './icons/SpinnerIcon';

interface ResultsDisplayProps {
  output: SearchResult | null;
  searchParams: SearchParams | null;
  isLoading: boolean;
  onQuestionClick: (q: string) => void;
  onAnalysisClick: (p: string) => void;
  onSave: (p: SearchParams, r: SearchResult) => void;
  onRemoveSave: (p: SearchParams) => void;
  isSaved: boolean;
  onJudgeClick: (n: string) => void;
}

const IntelligenceSkeleton = () => (
  <div className="flex flex-col gap-12 animate-pulse p-8 md:p-12">
    <div className="space-y-6">
       <div className="h-3 bg-slate-800 w-24 rounded-full"></div>
       <div className="h-10 bg-slate-800 w-3/4 rounded-lg"></div>
       <div className="h-64 bg-slate-800/50 w-full rounded-xl"></div>
    </div>
  </div>
);

export default function ResultsDisplay({ output, searchParams, isLoading, onQuestionClick, onAnalysisClick, onSave, onRemoveSave, isSaved, onJudgeClick }: ResultsDisplayProps): React.ReactNode {
  const dossierRef = useRef<HTMLDivElement>(null);
  const [isExporting, setIsExporting] = useState(false);
  const dossierId = useMemo(() => Math.random().toString(16).substring(2, 8).toUpperCase(), []);

  const handleExportPDF = async () => {
    if (!dossierRef.current || !output) return;
    setIsExporting(true);

    const element = dossierRef.current;

    // Inject a special class to force "Print Mode" styles (Light background, black text)
    element.classList.add('pdf-export-mode');

    const opt = {
      margin: [15, 15, 15, 15],
      filename: `LEGAL_INTEL_REPORT_${dossierId}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { 
        scale: 2.5, 
        useCORS: true, 
        backgroundColor: '#ffffff',
        logging: false,
        letterRendering: true
      },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
      pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
    };

    try {
      // @ts-ignore
      await html2pdf().set(opt).from(element).save();
    } catch (e) {
      console.error("PDF Export Failure", e);
    } finally {
      // Clean up the injected class after capture
      element.classList.remove('pdf-export-mode');
      setIsExporting(false);
    }
  };

  if (!output && !isLoading) return null;

  return (
    <div className="flex flex-col gap-10 pb-24 entry-animation">
      {isLoading && (!output || !output.summary) ? (
        <IntelligenceSkeleton />
      ) : output ? (
        <div className="flex flex-col gap-10">

          {/* Main Intelligence Dossier */}
          <div ref={dossierRef} className="flex flex-col gap-12 bg-slate-950 border border-slate-800 p-8 md:p-16 shadow-2xl relative overflow-hidden rounded-2xl transition-colors duration-300">

            {/* PDF Exclusive Cover Page Metadata (Hidden in UI, visible in PDF via classes) */}
            <div className="hidden pdf-only flex flex-col gap-4 border-b-2 border-slate-900 pb-12 mb-8">
              <div className="flex justify-between items-center">
                <span className="text-2xl font-black italic">DENVER COURT COPILOT</span>
                <span className="text-xs font-mono">REPORT_UID: {dossierId}</span>
              </div>
              <h1 className="text-4xl font-black uppercase tracking-tighter">Strategic Analysis Report</h1>
              <div className="grid grid-cols-2 gap-8 mt-4">
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Subject</span>
                  <span className="text-sm font-semibold">{searchParams?.query}</span>
                </div>
                <div className="flex flex-col">
                  <span className="text-[10px] font-bold text-slate-500 uppercase">Generated</span>
                  <span className="text-sm font-semibold">{new Date().toLocaleString()}</span>
                </div>
              </div>
            </div>

            {/* Dossier Header */}
            <div className="flex flex-col md:flex-row justify-between items-start border-b border-slate-800 pb-12 mb-4 gap-6">
              <div className="flex flex-col gap-3">
                <div className="flex items-center gap-3">
                  <span className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></span>
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] section-index-label">Verified_Intelligence_Stream</span>
                </div>
                <h2 className="text-4xl md:text-5xl font-black text-white italic tracking-tighter uppercase leading-none">
                  Strategic Dossier: <span className="text-blue-500/80">{dossierId}</span>
                </h2>
                <p className="text-xs text-slate-400 font-medium tracking-wide max-w-xl">
                  Subject: {searchParams?.query.substring(0, 80)}...
                </p>
              </div>
              <div className="text-right flex flex-col gap-1 font-mono text-[9px] text-slate-600 section-index-label">
                <span className="uppercase">Origin: NODE_0X42_DNVR</span>
                <span className="uppercase">Gen_Timestamp: {new Date().toLocaleString()}</span>
                <span className="uppercase">Classification: Attorney_Privileged</span>
              </div>
            </div>

            {/* SECTION_01: Executive Summary */}
            <div className="relative page-break-avoid">
              <div className="absolute -left-12 top-0 text-[10px] font-black text-blue-500/20 rotate-180 [writing-mode:vertical-lr] hidden md:block section-index-label">
                SECTION_01_SUMMARY
              </div>
              <div className="max-w-4xl mx-auto">
                <div className="prose prose-invert prose-2xl max-w-none text-slate-200 leading-relaxed font-light
                  prose-h1:text-4xl prose-h1:font-black prose-h1:italic prose-h1:mb-8 prose-h1:tracking-tighter prose-h1:text-white
                  prose-h2:text-[11px] prose-h2:text-blue-400/60 prose-h2:uppercase prose-h2:tracking-[0.8em] prose-h2:border-b prose-h2:border-slate-800 prose-h2:pb-4 prose-h2:mt-16 prose-h2:font-black
                  prose-p:mb-8 prose-p:text-xl prose-p:font-light prose-p:leading-relaxed
                  prose-strong:text-white prose-strong:font-black prose-strong:italic
                  prose-li:text-slate-300 prose-li:mb-4 prose-li:text-lg">
                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{output.summary}</ReactMarkdown>
                  {output.isSummaryStreaming && <span className="inline-block w-2 h-6 bg-blue-500 animate-pulse align-middle ml-2"></span>}
                </div>
              </div>
            </div>

            {/* SECTION_02: Adversarial Strategy Matrix */}
            <div className="relative mt-12 page-break-avoid">
              <div className="absolute -left-12 top-0 text-[10px] font-black text-red-500/20 rotate-180 [writing-mode:vertical-lr] hidden md:block section-index-label">
                SECTION_02_ADVERSARIAL
              </div>
              <AdversarialStrategyWidget strategy={output.adversarialStrategy} isLoading={output.isAdversarialLoading} />
            </div>

            {/* SECTION_03: Personnel & Evidence */}
            <div className="grid grid-cols-1 xl:grid-cols-2 gap-10 mt-12 page-break-avoid">
              {output.identifiedJudges && output.identifiedJudges.length > 0 && (
                <div className="relative">
                   <div className="absolute -left-12 top-0 text-[10px] font-black text-slate-500/20 rotate-180 [writing-mode:vertical-lr] hidden md:block section-index-label">
                    SECTION_03A_PERSONNEL
                  </div>
                  <IdentifiedJudges judges={output.identifiedJudges} isLoading={output.isIdentifiedJudgesLoading} onJudgeClick={onJudgeClick} />
                </div>
              )}

              <div className="bg-slate-900/40 border border-slate-800 p-10 rounded-xl relative group">
                <div className="absolute -left-12 top-0 text-[10px] font-black text-slate-500/20 rotate-180 [writing-mode:vertical-lr] hidden md:block section-index-label">
                  SECTION_03B_SOURCES
                </div>
                <div className="flex items-center gap-4 mb-8 border-b border-slate-800 pb-5">
                  <GlobeIcon className="w-5 h-5 text-blue-500/60" />
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest section-index-label">Intercepted_Dossier_Nodes</h4>
                </div>
                <div className="flex flex-col gap-3">
                  {output.sources.slice(0, 6).map((s, i) => (
                    <a 
                      key={i} 
                      href={s.uri} 
                      target="_blank" 
                      rel="noreferrer" 
                      className="flex items-center justify-between p-4 bg-slate-950/50 border border-slate-800 hover:border-blue-500/30 hover:bg-slate-800/30 transition-all group/src"
                    >
                      <div className="flex items-center gap-4 truncate">
                        <span className="text-[9px] font-mono text-slate-600">NODE_{i}</span>
                        <span className="truncate text-sm font-semibold text-slate-400 group-hover/src:text-white transition-colors">{s.title}</span>
                      </div>
                      <span className="text-[8px] font-black text-blue-500/0 group-hover/src:text-blue-500/100 transition-all uppercase tracking-tighter">View_Raw</span>
                    </a>
                  ))}
                </div>
              </div>
            </div>

            {/* SECTION_04: Temporal Vector Map */}
            {output.timelineEvents && output.timelineEvents.length > 0 && (
              <div className="relative mt-12 page-break-avoid">
                <div className="absolute -left-12 top-0 text-[10px] font-black text-slate-500/20 rotate-180 [writing-mode:vertical-lr] hidden md:block section-index-label">
                  SECTION_04_CHRONOLOGY
                </div>
                <div className="border-t border-slate-800 pt-16">
                  <TimelineChart events={output.timelineEvents} isLoading={output.isTimelineLoading} />
                </div>
              </div>
            )}

            {/* Dossier Terminal Footer */}
            <div className="mt-20 pt-10 border-t border-slate-800/50 text-center flex flex-col gap-3">
              <span className="text-[9px] font-black text-slate-700 uppercase tracking-[1.2em] section-index-label">End_Of_Transmission // Dossier_Complete</span>
              <div className="flex justify-center items-center gap-6 opacity-20 section-index-label">
                <span className="text-[7px] font-mono uppercase">Version: 4.0.21</span>
                <span className="text-[7px] font-mono uppercase">Encryption: AES_256_RSA</span>
                <span className="text-[7px] font-mono uppercase">Node: DNVR_SEC_4</span>
              </div>
            </div>
          </div>

          {/* Dossier Control Palette (Floating/Sticky feel) */}
          <div className="sticky bottom-6 flex flex-col md:flex-row justify-between items-center bg-slate-900 border border-slate-700 p-6 rounded-2xl shadow-[0_-20px_50px_rgba(0,0,0,0.5)] z-40 backdrop-blur-xl">
            <div className="flex items-center gap-6">
               <div className="flex flex-col">
                  <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Active_Session</span>
                  <span className="text-xs font-bold text-slate-400">Dossier_{dossierId}</span>
               </div>
               <div className="h-8 w-px bg-slate-800"></div>
               <div className="hidden lg:block">
                  <FollowUpQuestions questions={output.followUpQuestions || []} onQuestionClick={onQuestionClick} />
               </div>
            </div>
            <div className="flex gap-4 mt-6 md:mt-0">
              <button 
                onClick={handleExportPDF}
                disabled={isExporting}
                className="flex items-center gap-3 px-8 py-4 bg-white text-black font-black rounded-lg hover:bg-slate-200 transition-all disabled:opacity-50 active:scale-95 shadow-xl"
              >
                {isExporting ? <SpinnerIcon className="w-4 h-4 animate-spin text-black" /> : <DownloadIcon className="w-4 h-4 text-black" />}
                <span className="text-xs uppercase tracking-widest">{isExporting ? 'Generating...' : 'Export_Report'}</span>
              </button>
              <button 
                onClick={() => isSaved ? onRemoveSave(searchParams!) : onSave(searchParams!, output)} 
                className={`p-4 rounded-lg border transition-all active:scale-95 ${isSaved ? 'bg-blue-600 text-white border-blue-500 shadow-lg shadow-blue-500/20' : 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white hover:bg-slate-700'}`}
              >
                {isSaved ? <BookmarkFilledIcon className="w-5 h-5" /> : <BookmarkIcon className="w-5 h-5" />}
              </button>
            </div>
          </div>

          {/* Secondary Information Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <RelatedQueries queries={output.relatedQueries || []} onQueryClick={onQuestionClick} />
            <div className="bg-slate-900/30 p-8 rounded-xl border border-slate-800/50 flex flex-col justify-center items-center text-center gap-4">
               <span className="text-[10px] font-black text-slate-600 uppercase tracking-[0.4em]">Neural_Status</span>
               <p className="text-xs text-slate-500 italic max-w-xs">AI models are synthesizing data from public records. Verify specific case numbers with the Clerk of Court.</p>
            </div>
          </div>

        </div>
      ) : null}

      <style>{`
        .prose blockquote { border-left: 4px solid #3b82f6; background: rgba(59, 130, 246, 0.05); padding: 1.5rem; font-style: italic; color: #94a3b8; }
        .prose strong { color: #fff; font-weight: 800; }
        .prose h2 { font-family: 'JetBrains Mono', monospace; }

        .page-break-avoid {
          page-break-inside: avoid;
        }

        @media screen {
          .pdf-only { display: none; }
        }

        .pdf-export-mode .pdf-only {
