          <div ref={dossierRef} className="flex flex-col gap-12 bg-slate-950 border border-slate-800 p-8 md:p-16 shadow-2xl relative overflow-hidden rounded-2xl transition-colors duration-300">

            {/* PRINT-ONLY COVER SEGMENT */}
