              <div className="flex justify-between items-center">
                <div className="flex flex-col">
                  <span className="text-3xl font-black italic tracking-tighter text-blue-600">DENVER COURT COPILOT</span>
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mt-1">Autonomous Legal Intelligence Hub</span>
                </div>
                <div className="flex flex-col items-end">
                  <span className="text-[9px] font-mono font-bold px-2 py-1 bg-slate-100 border border-slate-200">REPORT_ID: {dossierId}</span>
                  <span className="text-[9px] font-mono text-slate-400 mt-1 uppercase">Confidential: Level_4_Access</span>
                </div>
              </div>
              <div className="mt-8 space-y-2">
                <h1 className="text-5xl font-black uppercase tracking-tighter leading-tight">Strategic Intelligence<br/>Analysis Report</h1>
              </div>
              <div className="grid grid-cols-2 gap-12 mt-10 pt-10 border-t border-slate-100">
                <div className="flex flex-col gap-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Primary Objective</span>
                  <span className="text-sm font-bold leading-tight">{searchParams?.query}</span>
                </div>
                <div className="flex flex-col gap-2">
                  <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Generation Node</span>
                  <span className="text-sm font-mono">DEN_JUDICIAL_01 // {new Date().toLocaleDateString()} {new Date().toLocaleTimeString()}</span>
                </div>
              </div>
            </div>

            {/* Dossier Header (Visible in UI and PDF) */}
            <div className="flex flex-col md:flex-row justify-between items-start border-b border-slate-800 pb-12 mb-4 gap-6 page-break-avoid">
              <div className="flex flex-col gap-3">
