import React, { useRef, useLayoutEffect, useState, useMemo } from 'react';
import { type SearchParams, DateRange } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import HistoryIcon from './icons/HistoryIcon';
import { MAX_QUERY_LENGTH, LEGAL_SUGGESTIONS } from '../constants';

interface SearchFormProps {
  params: SearchParams;
  setParams: React.Dispatch<React.SetStateAction<SearchParams>>;
  onSearch: () => void;
  isLoading: boolean;
  onClear: () => void;
  onSelectHistory: (params: SearchParams) => void;
  onSave: () => void;
  canSave: boolean;
}

export default function SearchForm({ 
  params, 
  setParams, 
  onSearch, 
  isLoading, 
  onClear,
  onSelectHistory,
  onSave,
  canSave
}: SearchFormProps): React.ReactNode {
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const [showSuggestions, setShowSuggestions] = useState(false);

  const isOverLimit = params.query.length > MAX_QUERY_LENGTH;

  const filteredSuggestions = useMemo(() => {
    const lastWord = params.query.split(/\s+/).pop()?.toLowerCase() || '';
    if (lastWord.length < 2) return [];
    return LEGAL_SUGGESTIONS.filter(s => s.toLowerCase().includes(lastWord)).slice(0, 5);
  }, [params.query]);

  useLayoutEffect(() => {
    const textarea = textareaRef.current;
    if (textarea) {
      textarea.style.height = 'auto';
      textarea.style.height = `${Math.max(120, textarea.scrollHeight)}px`;
    }
  }, [params.query]);

  const handleSuggestionClick = (suggestion: string) => {
    const words = params.query.split(/\s+/);
    words.pop(); // remove last typed partial
    const newQuery = [...words, suggestion].join(' ').trim() + ' ';
    setParams({ ...params, query: newQuery });
    setShowSuggestions(false);
    textareaRef.current?.focus();
  };

  return (
    <div className="flex flex-col w-full bg-slate-900/50 backdrop-blur-md relative">
      {/* SaaS Style Status Bar */}
      <div className="flex justify-between items-center px-6 py-3 border-b border-slate-700/50 bg-slate-800/40">
        <div className="flex items-center gap-3">
          <div className={`w-1.5 h-1.5 rounded-full ${isLoading ? 'bg-blue-400 animate-pulse' : isOverLimit ? 'bg-red-500' : 'bg-emerald-500'}`}></div>
          <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">
            {isOverLimit ? 'System Alert: Buffer Overflow' : isLoading ? 'Command Center Status: Operational' : 'Ready for Deployment'}
          </span>
        </div>
        <div className="flex items-center gap-4">
          <span className={`text-[9px] font-mono ${isOverLimit ? 'text-red-500 font-bold' : 'text-slate-500'}`}>
            Query Buffer: {params.query.length.toLocaleString()} / {MAX_QUERY_LENGTH.toLocaleString()}
          </span>
        </div>
      </div>

      <div className="p-6 md:p-8 space-y-8">
        {/* Main Command Input */}
        <div className="space-y-3 relative">
          <div className="flex justify-between items-end">
            <label className="text-xs font-bold text-slate-400 uppercase tracking-wider">Mission Objective & Legal Context</label>
            <span className="text-[10px] text-slate-600 italic">Describe your case or strategy goals</span>
          </div>
          <div className="relative group">
            <textarea
              ref={textareaRef}
              value={params.query}
              onChange={(e) => {
                setParams({...params, query: e.target.value});
                setShowSuggestions(true);
              }}
              onBlur={() => setTimeout(() => setShowSuggestions(false), 200)}
              placeholder="e.g., 'Analyze sentencing patterns for Judge Baumann in 2024 drug felony cases' or 'Draft a motion to dismiss based on improper service'..."
              className={`w-full bg-slate-950/50 border ${isOverLimit ? 'border-red-500 focus:ring-red-500/20' : 'border-slate-800 focus:ring-blue-500/30 focus:border-blue-500'} rounded-xl p-6 text-xl text-white placeholder:text-slate-700 focus:outline-none focus:ring-2 transition-all resize-none shadow-2xl leading-relaxed`}
              disabled={isLoading}
            />

            {/* Suggestions Dropdown */}
            {showSuggestions && filteredSuggestions.length > 0 && (
              <div className="absolute left-0 right-0 top-full mt-2 z-[60] bg-slate-900 border border-slate-700 shadow-[0_20px_50px_rgba(0,0,0,0.5)] rounded-xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                <div className="px-4 py-2 border-b border-slate-800 bg-slate-800/50">
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Strategic Auto-Complete</span>
                </div>
                {filteredSuggestions.map((s, i) => (
                  <button
                    key={i}
                    onClick={() => handleSuggestionClick(s)}
                    className="w-full text-left px-6 py-4 text-sm text-slate-300 hover:bg-blue-600 hover:text-white transition-colors flex items-center justify-between group"
                  >
                    <span>{s}</span>
                    <span className="text-[10px] text-slate-600 group-hover:text-blue-200 font-mono">APPEND_CMD</span>
                  </button>
                ))}
              </div>
            )}
          </div>
          {isOverLimit && (
            <p className="text-[10px] text-red-500 font-bold uppercase tracking-widest mt-1">
              Payload exceeds tactical limit. Optimization required.
            </p>
          )}
        </div>

        {/* Strategic Parameters Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest pl-1">Target Entity</label>
            <input 
              type="text" 
              placeholder="Name or Case ID" 
              value={params.partyName || ''} 
              onChange={(e) => setParams({...params, partyName: e.target.value})} 
              className="w-full bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all outline-none"
            />
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest pl-1">Temporal Scope</label>
            <div className="relative">
              <select 
                value={params.dateRange} 
                onChange={(e) => setParams({...params, dateRange: e.target.value as DateRange})} 
                className="w-full bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all outline-none appearance-none cursor-pointer"
              >
                <option value={DateRange.ANY}>All Historical Data</option>
                <option value={DateRange.DAY}>Past 24 Hours</option>
                <option value={DateRange.WEEK}>Past 7 Days</option>
                <option value={DateRange.MONTH}>Past 30 Days</option>
                <option value={DateRange.YEAR}>Past 365 Days</option>
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-40">▼</div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest pl-1">Legal Schema</label>
            <div className="relative">
              <select 
                value={params.caseType} 
                onChange={(e) => setParams({...params, caseType: e.target.value as any})} 
                className="w-full bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all outline-none appearance-none cursor-pointer"
              >
                <option value="all">Universal Context</option>
                <option value="civil">Civil (Rules 1-120)</option>
                <option value="criminal">Criminal (Title 16)</option>
                <option value="family">Family (Title 14)</option>
                <option value="probate">Probate (Title 15)</option>
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-40">▼</div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest pl-1">Jurisdiction</label>
            <div className="relative">
              <select 
                value={params.jurisdiction} 
                onChange={(e) => setParams({...params, jurisdiction: e.target.value as any})} 
                className="w-full bg-slate-800/50 border border-slate-700 rounded-lg p-3 text-sm text-slate-200 focus:ring-2 focus:ring-blue-500/20 focus:border-blue-400 transition-all outline-none appearance-none cursor-pointer"
              >
                <option value="all">Denver Combined Courts</option>
                <option value="denver_district">2nd Judicial District</option>
                <option value="denver_county">Denver County Court</option>
              </select>
              <div className="absolute right-3 top-1/2 -translate-y-1/2 pointer-events-none opacity-40">▼</div>
            </div>
          </div>
        </div>

        {/* Deployment Actions */}
        <div className="flex flex-col sm:flex-row gap-3 pt-4">
          <button 
            onClick={onSearch}
            disabled={isLoading || !params.query.trim() || isOverLimit}
            className="flex-[4] relative group bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-600 text-white font-bold py-5 rounded-xl shadow-xl shadow-blue-900/10 transition-all flex items-center justify-center gap-3 active:scale-[0.99] border-t border-white/10"
          >
            {isLoading ? (
              <>
                <SpinnerIcon className="w-5 h-5 animate-spin" />
                <span className="uppercase tracking-widest text-xs font-black">Synthesizing Strategy...</span>
              </>
            ) : (
              <span className="uppercase tracking-[0.2em] text-sm font-black">Execute Intelligence Harvest</span>
            )}
          </button>

          <button 
            onClick={onClear} 
            className="flex-1 bg-slate-800/50 hover:bg-slate-700 text-slate-400 hover:text-white font-bold py-5 rounded-xl border border-slate-700 transition-all text-xs uppercase tracking-widest"
          >
            Clear
          </button>

          <button 
            onClick={() => {
                console.debug("Operational history request received");
            }}
            className="px-6 bg-slate-800/50 hover:bg-slate-700 text-slate-400 hover:text-white rounded-xl border border-slate-700 transition-all"
            title="Operational History"
          >
            <HistoryIcon className="w-5 h-5" />
          </button>
        </div>
      </div>
    </div>
  );
}

