import React, { useState, useCallback, useEffect } from 'react';
import { SearchType, type SearchParams, DateRange, CaseStatus, type Bookmark, CaseType, Jurisdiction, type SearchResult, type DocumentAnalysisResult, type CrossReferenceResult } from './types';
import { searchWebWithGemini, analyzeDocument, crossReferenceDocuments, generateNarrativeMap } from './services/geminiService';
import { getCachedResult, setCachedResult } from './services/cacheService';
import { addToHistory } from './services/historyService';
import { getBookmarks, saveBookmark, removeBookmark, isSearchBookmarked, isDocBookmarked, isCrossRefBookmarked, generateSearchKey, generateDocKey, generateCrossRefKey } from './services/bookmarkService';
import { MAX_QUERY_LENGTH } from './constants';
import Header from './components/Header';
import Banner from './components/Banner';
import SearchForm from './components/SearchForm';
import ResultsDisplay from './components/ResultsDisplay';
import Examples from './components/Examples';
import Bookmarks from './components/Bookmarks';
import JudgeDetailModal from './components/JudgeDetailModal';
import DocumentAnalysisModal from './components/DocumentAnalysisModal';
import CrossReferenceModal from './components/CrossReferenceModal';
import NarrativeMapper from './components/NarrativeMapper';

export default function App(): React.ReactNode {
  const [searchParams, setSearchParams] = useState<SearchParams>({
    query: '',
    searchType: SearchType.SEARCH,
    listCount: undefined,
    dateRange: DateRange.ANY,
    siteRestrict: '',
    fileType: '',
    partyName: '',
    caseNumber: '',
    caseStatus: CaseStatus.ALL,
    caseType: CaseType.ALL,
    jurisdiction: Jurisdiction.ALL,
  });
  const [currentSearchParamsForResults, setCurrentSearchParamsForResults] = useState<SearchParams | null>(null);
  const [output, setOutput] = useState<SearchResult | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [bookmarks, setBookmarks] = useState<Bookmark[]>([]);

  const [showJudgeModal, setShowJudgeModal] = useState(false);
  const [selectedJudgeName, setSelectedJudgeName] = useState<string | null>(null);

  const [showDocumentAnalysisModal, setShowDocumentAnalysisModal] = useState(false);
  const [documentAnalysisResult, setDocumentAnalysisResult] = useState<DocumentAnalysisResult | null>(null);
  const [isDocumentAnalysisLoading, setIsDocumentAnalysisLoading] = useState<boolean>(false);
  const [auditFileData, setAuditFileData] = useState<{b64: string, mime: string, name: string} | null>(null);

  const [showCrossRefModal, setShowCrossRefModal] = useState(false);
  const [crossRefResult, setCrossRefResult] = useState<CrossReferenceResult | null>(null);
  const [isCrossRefLoading, setIsCrossRefLoading] = useState(false);

  const [showNarrativeMapper, setShowNarrativeMapper] = useState(false);
  const [narrativeInitialData, setNarrativeInitialData] = useState<{b64: string, mime: string, name: string} | null>(null);

  useEffect(() => {
    setBookmarks(getBookmarks());
  }, []);

  const executeSearch = useCallback(async (params: SearchParams) => {
    const finalParams: SearchParams = { ...params, query: params.query.trim() };

    if (!finalParams.query) {
      setError('Neural scan requires query input.');
      return;
    }
    if (finalParams.query.length > MAX_QUERY_LENGTH) {
      setError(`Payload exceeds char limit.`);
      return;
    }

    const cachedResult = getCachedResult(finalParams);
    if (cachedResult) {
      setOutput({
        ...cachedResult,
        isSummaryStreaming: false,
        isFollowUpQuestionsLoading: false,
        isRelatedQueriesLoading: false,
        isTimelineLoading: false,
        isIdentifiedJudgesLoading: false,
      });
      setCurrentSearchParamsForResults(finalParams);
      setError(null);
      return;
    }

    setIsLoading(true);
    setError(null);
    setOutput({
      summary: '',
      sources: [],
      followUpQuestions: [],
      relatedQueries: [],
      timelineEvents: [],
      identifiedJudges: [],
      isSummaryStreaming: true,
      isFollowUpQuestionsLoading: false,
      isRelatedQueriesLoading: false,
      isTimelineLoading: false,
      isIdentifiedJudgesLoading: false,
    });
    setCurrentSearchParamsForResults(finalParams);

    try {
      const result = await searchWebWithGemini(finalParams, (partial) => {
        setOutput(prev => ({ ...prev!, ...partial }));
      });
      setOutput(prev => ({
          ...prev!,
          ...result,
          isSummaryStreaming: false,
      }));
      setCachedResult(finalParams, result);
      addToHistory(finalParams);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Dossier synthesis failure.');
      setOutput(null);
    } finally {
      setIsLoading(false);
    }
  }, []);

  const handleSearch = useCallback(() => executeSearch(searchParams), [searchParams, executeSearch]);

  const handleSaveResult = (params: SearchParams, result: SearchResult) => {
    const key = generateSearchKey(params);
    saveBookmark({ key, type: 'search', params, result, savedAt: Date.now() });
    setBookmarks(getBookmarks());
  };

  const handleRemoveSave = (params: SearchParams) => {
    removeBookmark(generateSearchKey(params));
    setBookmarks(getBookmarks());
  };

  const handleViewBookmark = (bookmark: Bookmark) => {
    if (bookmark.type === 'search') {
        setSearchParams(bookmark.params);
        setOutput({ ...bookmark.result, isSummaryStreaming: false });
        setCurrentSearchParamsForResults(bookmark.params);
    } else if (bookmark.type === 'document_analysis') {
        setDocumentAnalysisResult(bookmark.result);
        setShowDocumentAnalysisModal(true);
    } else if (bookmark.type === 'cross_reference') {
        setCrossRefResult(bookmark.result);
        setShowCrossRefModal(true);
    }
  };

  const launchNarrativeFromAudit = () => {
    if (!auditFileData) return;
    setNarrativeInitialData(auditFileData);
    setShowDocumentAnalysisModal(false);
    setShowNarrativeMapper(true);
  };

  return (
    <div className="min-h-screen pb-12 flex flex-col bg-[#0a0a0a]">
      <Banner />

      <div className="flex-grow flex flex-col lg:flex-row max-w-[1800px] mx-auto w-full px-4 lg:px-12 gap-12 mt-12">

        {/* Sidebar */}
        <aside className="lg:w-96 flex flex-col gap-12 order-2 lg:order-1">
          <div className="tech-plate p-10 flex flex-col gap-10">
            <div className="calibration-marks mark-tl mark-bl"></div>
            <Header 
              onAnalyzeDocumentClick={() => { setAuditFileData(null); setShowDocumentAnalysisModal(true); }} 
              onCrossReferenceClick={() => setShowCrossRefModal(true)} 
              onNarrativeMapperClick={() => { setNarrativeInitialData(null); setShowNarrativeMapper(true); }}
            />
          </div>

          <Bookmarks 
            bookmarks={bookmarks}
            onView={handleViewBookmark}
            onDelete={(key) => { removeBookmark(key); setBookmarks(getBookmarks()); }}
          />
        </aside>

        {/* Main Console */}
        <main className="flex-grow flex flex-col gap-12 order-1 lg:order-2">
          <div className="tech-plate overflow-hidden">
            <div className="calibration-marks mark-tl mark-tr mark-bl mark-br"></div>
            <SearchForm
              params={searchParams}
              setParams={setSearchParams}
              onSearch={handleSearch}
              isLoading={isLoading}
              onClear={() => { setOutput(null); setSearchParams({...searchParams, query: ''}); }}
              onSelectHistory={(p) => { setSearchParams(p); executeSearch(p); }}
              onSave={() => currentSearchParamsForResults && output && handleSaveResult(currentSearchParamsForResults, output)}
              onImportPDF={() => { setAuditFileData(null); setShowDocumentAnalysisModal(true); }}
              canSave={!!output && !!currentSearchParamsForResults}
            />

            <div className="px-10 pb-10 pt-6">
              <Examples onSelectExample={(ex) => setSearchParams({...searchParams, ...ex})} />
            </div>
          </div>

          {error && (
            <div className="bg-red-950/20 border border-red-900/40 p-6 etched-label text-red-500 flex items-center gap-4 animate-pulse">
              <div className="w-2 h-2 bg-red-500 rounded-full"></div>
              SYSTEM_FAULT: {error}
            </div>
          )}

          <ResultsDisplay
            output={output}
            searchParams={currentSearchParamsForResults}
            isLoading={isLoading}
            onQuestionClick={(q) => { setSearchParams({...searchParams, query: q}); executeSearch({...searchParams, query: q}); }}
            onAnalysisClick={(prompt) => { /* logic */ }}
            onSave={handleSaveResult}
            onRemoveSave={handleRemoveSave}
            isSaved={currentSearchParamsForResults ? isSearchBookmarked(currentSearchParamsForResults) : false}
            onJudgeClick={(name) => { setSelectedJudgeName(name); setShowJudgeModal(true); }}
          />
        </main>
      </div>

      <footer className="mt-20 text-center etched-label opacity-20 tracking-[0.6em]">
        PRECISION_LEGAL_ANALYSIS_NODE // GEMINI_v3_CORE
      </footer>

      {showJudgeModal && selectedJudgeName && (
        <JudgeDetailModal judgeName={selectedJudgeName} onClose={() => setShowJudgeModal(false)} />
      )}
      {showDocumentAnalysisModal && (
        <DocumentAnalysisModal
          onClose={() => setShowDocumentAnalysisModal(false)}
          onAnalyze={async (b64, mime, name) => {
            setAuditFileData({b64, mime, name});
            setIsDocumentAnalysisLoading(true);
            try { setDocumentAnalysisResult(await analyzeDocument(b64, mime, name)); }
            catch (e) { console.error(e); }
            finally { setIsDocumentAnalysisLoading(false); }
          }}
          result={documentAnalysisResult}
          isLoading={isDocumentAnalysisLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateDocKey(res.fileName),
              type: 'document_analysis',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateDocKey(r.fileName));
            setBookmarks(getBookmarks());
          }}
          onMapNarrative={launchNarrativeFromAudit}
          isSaved={documentAnalysisResult ? isDocBookmarked(documentAnalysisResult.fileName) : false}
        />
      )}
      {showCrossRefModal && (
        <CrossReferenceModal
          onClose={() => setShowCrossRefModal(false)}
          onAnalyze={async (a, am, an, b, bm, bn) => {
            setIsCrossRefLoading(true);
            try { setCrossRefResult(await crossReferenceDocuments(a, am, an, b, bm, bn)); }
            catch(e) { console.error(e); }
            finally { setIsCrossRefLoading(false); }
          }}
          result={crossRefResult}
          isLoading={isCrossRefLoading}
          error={null}
          onSave={(res) => {
            saveBookmark({
              key: generateCrossRefKey(res.fileAName, res.fileBName),
              type: 'cross_reference',
              result: res,
              savedAt: Date.now()
            });
            setBookmarks(getBookmarks());
          }}
          onRemoveSave={(r) => {
            removeBookmark(generateCrossRefKey(r.fileAName, r.fileBName));
            setBookmarks(getBookmarks());
          }}
          isSaved={crossRefResult ? isCrossRefBookmarked(crossRefResult.fileAName, crossRefResult.fileBName) : false}
        />
      )}
      {showNarrativeMapper && (
        <NarrativeMapper 
          onClose={() => { setShowNarrativeMapper(false); setNarrativeInitialData(null); }} 
          initialData={narrativeInitialData}
          onGenerate={async (b, m, n) => await generateNarrativeMap(b, m, n)}
        />
      )}
    </div>
  );
}

import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import { NarrativeMapResult, NarrativeNode, NarrativeLink, TimelineEvent } from '../types';
import SpinnerIcon from './icons/SpinnerIcon';
import CloseIcon from './icons/CloseIcon';
import BrainCircuitIcon from './icons/BrainCircuitIcon';
import UserIcon from './icons/UserIcon';
import GavelIcon from './icons/GavelIcon';
import GlobeIcon from './icons/GlobeIcon';
import DocumentIcon from './icons/DocumentIcon';
import AlertIcon from './icons/AlertIcon';
import CalendarIcon from './icons/CalendarIcon';
import DownloadIcon from './icons/DownloadIcon';
import ChevronDownIcon from './icons/ChevronDownIcon';

interface NarrativeMapperProps {
    onClose: () => void;
    onGenerate: (base64Content: string, mimeType: string, fileName: string) => Promise<NarrativeMapResult>;
    initialData?: { b64: string, mime: string, name: string } | null;
}

const getNodeIcon = (type: string, className = "w-5 h-5") => {
    switch (type) {
        case 'person': return <UserIcon className={className} />;
        case 'location': return <GlobeIcon className={className} />;
        case 'institution': return <GavelIcon className={className} />;
        case 'event': return <CalendarIcon className={className} />;
        default: return <DocumentIcon className={className} />;
    }
};

const EvidenceBadge: React.FC<{ tag: string }> = ({ tag }) => {
    let borderColor = "#6e501a";
    let textColor = "#a0a0a0";
    if (tag.includes("Brady")) { borderColor = "#ef4444"; textColor = "#ef4444"; }
    else if (tag.includes("613")) { borderColor = "#b5892f"; textColor = "#e2c07d"; }
    return (
        <span className="px-2 py-0.5 rounded-[2px] text-[8px] font-black uppercase border tracking-tighter shadow-sm" style={{borderColor, color: textColor, backgroundColor: 'rgba(0,0,0,0.5)'}}>
            {tag}
        </span>
    );
};

const GraphView: React.FC<{ data: NarrativeMapResult; onNodeClick: (node: NarrativeNode) => void; activeNodeId: string | null; svgRef: React.RefObject<SVGSVGElement | null>; containerRef: React.RefObject<HTMLDivElement | null>; }> = ({ data, onNodeClick, activeNodeId, svgRef, containerRef }) => {
    const [positions, setPositions] = useState<Record<string, { x: number, y: number }>>({});
    const [draggingId, setDraggingId] = useState<string | null>(null);

    // Force-Directed Layout Simulation (Fruchterman-Reingold variant)
    useEffect(() => {
        const width = 800;
        const height = 600;
        const nodes = data.nodes;
        const links = data.links;

        if (nodes.length === 0) return;

        // 1. Initial positions (randomized slightly around center to break symmetry)
        const initialPos: Record<string, { x: number, y: number }> = {};
        nodes.forEach((node, i) => {
            const angle = (i / nodes.length) * 2 * Math.PI;
            initialPos[node.id] = { 
                x: 400 + Math.cos(angle) * 100 + (Math.random() - 0.5) * 50, 
                y: 300 + Math.sin(angle) * 100 + (Math.random() - 0.5) * 50 
            };
        });

        // 2. Simulation constants
        const iterations = 180;
        const k = Math.sqrt((width * height) / nodes.length) * 0.85; // Ideal distance
        let temp = width / 10; // Current "temperature" (maximum movement)

        const currentPos = { ...initialPos };

        for (let iter = 0; iter < iterations; iter++) {
            const displacements: Record<string, { dx: number, dy: number }> = {};
            nodes.forEach(n => displacements[n.id] = { dx: 0, dy: 0 });

            // Calculate Repulsion (Coulomb-like)
            for (let i = 0; i < nodes.length; i++) {
                for (let j = 0; j < nodes.length; j++) {
                    if (i === j) continue;
                    const u = nodes[i], v = nodes[j];
                    const dx = currentPos[u.id].x - currentPos[v.id].x;
                    const dy = currentPos[u.id].y - currentPos[v.id].y;
                    const distSq = dx * dx + dy * dy || 0.01;
                    const dist = Math.sqrt(distSq);

                    // Repulsive force: nodes act like same-charge magnets
                    const f = (k * k) / dist;
                    displacements[u.id].dx += (dx / dist) * f;
                    displacements[u.id].dy += (dy / dist) * f;
                }
            }

            // Calculate Attraction (Hooke-like)
            links.forEach(link => {
                const uId = link.source;
                const vId = link.target;
                if (!currentPos[uId] || !currentPos[vId]) return;

                const dx = currentPos[uId].x - currentPos[vId].x;
                const dy = currentPos[uId].y - currentPos[vId].y;
                const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;

                // Attractive force: links act like springs
                // Enhancement: Contradiction links are stronger and pull nodes tighter for visual clustering
                const forceMultiplier = link.type === 'contradiction' ? 2.5 : 1.0;
                const f = ((dist * dist) / k) * forceMultiplier;
                const dxNorm = (dx / dist) * f;
                const dyNorm = (dy / dist) * f;

                displacements[uId].dx -= dxNorm;
                displacements[uId].dy -= dyNorm;
                displacements[vId].dx += dxNorm;
                displacements[vId].dy += dyNorm;
            });

            // Apply Centering Force (Gravity)
            nodes.forEach(node => {
                const dx = currentPos[node.id].x - 400;
                const dy = currentPos[node.id].y - 300;
                const dist = Math.sqrt(dx * dx + dy * dy) || 0.01;

                // Enhancement: Brady nodes have significantly higher gravity to keep them in the central command view
                const baseGravity = 0.02;
                const gravity = !!node.bradyFlag ? 0.09 : baseGravity;

                displacements[node.id].dx -= dx * gravity;
                displacements[node.id].dy -= dy * gravity;
            });

            // Update positions
            nodes.forEach(node => {
                const disp = displacements[node.id];
                const dist = Math.sqrt(disp.dx * disp.dx + disp.dy * disp.dy) || 0.01;

                // Limit displacement by temperature
                currentPos[node.id].x += (disp.dx / dist) * Math.min(dist, temp);
                currentPos[node.id].y += (disp.dy / dist) * Math.min(dist, temp);

                // Boundary constraints (soft)
                currentPos[node.id].x = Math.max(60, Math.min(740, currentPos[node.id].x));
                currentPos[node.id].y = Math.max(60, Math.min(540, currentPos[node.id].y));
            });

            // Cooling schedule
            temp *= (1 - iter / iterations);
        }

        setPositions(currentPos);
    }, [data.nodes, data.links]);

    return (
        <div ref={containerRef} className="bg-[#050505] rounded-none overflow-hidden relative h-full w-full border border-[#6e501a]/20">
            <div className="absolute inset-0 opacity-[0.05] pointer-events-none" style={{ backgroundImage: 'radial-gradient(#b5892f 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>
            <svg 
              ref={svgRef} 
              width="100%" height="100%" 
              viewBox="0 0 800 600" 
              onMouseMove={(e) => { 
                if (draggingId) { 
                  const r = svgRef.current!.getBoundingClientRect(); 
                  setPositions(p => ({...p, [draggingId]: { x: (e.clientX - r.left) * (800/r.width), y: (e.clientY - r.top) * (600/r.height) }})); 
                } 
              }} 
              onMouseUp={() => setDraggingId(null)} 
              className="cursor-crosshair"
            >
                <defs>
                    <marker id="arrow" markerWidth="10" markerHeight="10" refX="32" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#6e501a" /></marker>
                    <marker id="arrow-contradiction" markerWidth="10" markerHeight="10" refX="32" refY="5" orient="auto"><path d="M0,0 L10,5 L0,10 Z" fill="#ef4444" /></marker>
                </defs>
                {data.links.map((l, i) => {
                    const s = positions[l.source], e = positions[l.target]; if (!s || !e) return null;
                    const isContradiction = l.type === 'contradiction';
                    const isInferred = l.type === 'inferred';
                    return (
                        <g key={i}>
                            <line 
                                x1={s.x} y1={s.y} x2={e.x} y2={e.y} 
                                stroke={isContradiction ? '#ef4444' : (isInferred ? '#6e501a' : '#b5892f')} 
                                strokeWidth={isContradiction ? "2" : "1"} 
                                strokeDasharray={isInferred ? "5,5" : "0"}
                                opacity="0.6" 
                                markerEnd={isContradiction ? "url(#arrow-contradiction)" : "url(#arrow)"} 
                            />
                            <foreignObject x={(s.x+e.x)/2 - 50} y={(s.y+e.y)/2 - 10} width="100" height="20">
                                <div className={`text-[8px] font-black text-center uppercase tracking-tighter ${isContradiction ? 'text-red-500' : 'text-[#6e501a]'}`}>{l.label}</div>
                            </foreignObject>
                        </g>
                    );
                })}
                {data.nodes.map(n => {
                    const p = positions[n.id]; if (!p) return null;
                    const isActive = activeNodeId === n.id;
                    const color = !!n.bradyFlag ? '#ef4444' : '#b5892f';
                    return (
                        <g key={n.id} transform={`translate(${p.x}, ${p.y})`} onClick={() => onNodeClick(n)} onMouseDown={(e) => { e.stopPropagation(); setDraggingId(n.id); }} className="cursor-pointer select-none">
                            <circle r="24" fill="#050505" stroke={isActive ? '#e2c07d' : color} strokeWidth={isActive ? "3" : "1"} className="transition-[stroke-width,stroke] duration-200" />
                            <foreignObject x="-12" y="-12" width="24" height="24" className="pointer-events-none">
                                <div className="flex justify-center" style={{color: !!n.bradyFlag ? '#ef4444' : '#b5892f'}}>
                                    {getNodeIcon(n.type, "w-6 h-6")}
                                </div>
                            </foreignObject>
                            <text y="42" fill="#efefef" fontSize="10" fontWeight="900" textAnchor="middle" className="uppercase tracking-widest pointer-events-none drop-shadow-lg">{n.label}</text>
                            {n.bradyFlag && <circle r="6" cx="18" cy="-18" fill="#ef4444" className="animate-pulse" />}
                        </g>
                    );
                })}
            </svg>
        </div>
    );
};

export default function NarrativeMapper({ onClose, onGenerate, initialData }: NarrativeMapperProps): React.ReactNode {
    const [file, setFile] = useState<File | null>(null);
    const [isLoading, setIsLoading] = useState(false);
    const [result, setResult] = useState<NarrativeMapResult | null>(null);
    const [selectedNode, setSelectedNode] = useState<NarrativeNode | null>(null);
    const [isExportMenuOpen, setIsExportMenuOpen] = useState(false);
    const [isExporting, setIsExporting] = useState(false);

    const svgRef = useRef<SVGSVGElement | null>(null);
    const containerRef = useRef<HTMLDivElement | null>(null);

    const handleGenerateInternal = useCallback(async (b64: string, mime: string, name: string) => {
        setIsLoading(true);
        try {
            const res = await onGenerate(b64, mime, name);
            setResult(res);
        } catch (e) {
            console.error("Mapping failure:", e);
        } finally {
            setIsLoading(false);
        }
    }, [onGenerate]);

    useEffect(() => {
        if (initialData) {
            handleGenerateInternal(initialData.b64, initialData.mime, initialData.name);
        }
    }, [initialData, handleGenerateInternal]);

    const handleManualGenerate = async () => {
        if (!file) return; 
        try {
            const b64 = await new Promise<string>((resolve, reject) => { 
                const rd = new FileReader(); 
                rd.onload = () => {
                    const res = rd.result as string;
                    if (res) resolve(res.split(',')[1]);
                    else reject(new Error("File read error"));
                }; 
                rd.onerror = () => reject(new Error("Dossier injection failed"));
                rd.readAsDataURL(file); 
            });
            await handleGenerateInternal(b64, file.type, file.name);
        } catch (e) {
            console.error("Manual mapping trigger error:", e);
        }
    };

    const handleExportPNG = async () => {
        if (!containerRef.current) return;
        setIsExporting(true);
        setIsExportMenuOpen(false);
        try {
            // @ts-ignore - html2canvas is globally available via script tag in index.html
            const canvas = await html2canvas(containerRef.current, {
                backgroundColor: '#050505',
                scale: 3, // Higher resolution
                useCORS: true,
                logging: false
            });
            const link = document.createElement('a');
            link.download = `NARRATIVE_MATRIX_${result?.nodes.length}_NODES.png`;
            link.href = canvas.toDataURL('image/png');
            link.click();
        } catch (err) {
            console.error("PNG Export Failed", err);
            alert("Strategic Capture Failed: Analysis stream interrupted.");
        } finally {
            setIsExporting(false);
        }
    };

    const handleExportSVG = () => {
        if (!svgRef.current) return;
        setIsExportMenuOpen(false);
        try {
            const serializer = new XMLSerializer();
            let source = serializer.serializeToString(svgRef.current);
            if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
                source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
            }
            if (!source.match(/^<svg[^>]+xmlns\:xlink="http\:\/\/www\.w3\.org\/1999\/xlink"/)) {
                source = source.replace(/^<svg/, '<svg xmlns:xlink="http://www.w3.org/1999/xlink"');
            }
            source = '<?xml version="1.0" standalone="no"?>\r\n' + source;
            const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
            const link = document.createElement('a');
            link.download = `NARRATIVE_MATRIX_${result?.nodes.length}_NODES.svg`;
            link.href = url;
            link.click();
        } catch (err) {
            console.error("SVG Export Failed", err);
        }
    };

    if (!result && !isLoading) {
        return (
            <div className="fixed inset-0 bg-[#050505]/95 backdrop-blur-md flex justify-center items-center z-50 p-4">
                <div className="bg-[#121212] border border-[#6e501a] p-10 max-w-xl w-full text-center relative">
                    <div className="absolute top-0 left-0 right-0 h-1 bg-[#b5892f]"></div>
                    <h2 className="text-3xl font-black text-[#efefef] tracking-tighter uppercase italic mb-6">Narrative Matrix Generator</h2>
                    <input type="file" accept="application/pdf" onChange={(e) => e.target.files && setFile(e.target.files[0])} className="hidden" id="f-mapper" />
                    <label htmlFor="f-mapper" className="block p-12 border border-dashed border-[#6e501a]/40 mb-10 cursor-pointer hover:bg-[#b5892f]/5">
                        <DocumentIcon className="w-12 h-12 text-[#6e501a] mx-auto mb-4" />
                        <span className="text-xs font-black text-[#e2c07d] uppercase tracking-widest">{file ? file.name : "Inject Discovery Data"}</span>
                    </label>
                    <button onClick={handleManualGenerate} disabled={!file} className="w-full py-5 bg-[#b5892f] text-[#050505] font-black uppercase italic tracking-tighter text-xl hover:bg-[#e2c07d] transition-all shadow-xl">Synchronise Narrative tracks</button>
                    <button onClick={onClose} className="mt-6 text-[#6e501a] text-[10px] font-black uppercase tracking-widest hover:text-[#efefef]">Abort Command</button>
                </div>
            </div>
        );
    }

    if (isLoading) return (
        <div className="fixed inset-0 bg-[#050505] flex flex-col items-center justify-center z-50">
            <SpinnerIcon className="w-16 h-16 text-[#b5892f] mb-8" />
            <div className="text-[10px] font-black text-[#6e501a] uppercase tracking-[0.6em] animate-pulse">Reconstructing Narrative Timeline...</div>
        </div>
    );

    return (
        <div className="fixed inset-0 bg-[#050505] z-50 flex flex-col animate-[fadeIn_0.3s_ease-out]">
            <div className="p-6 bg-[#121212] border-b border-[#6e501a]/30 flex justify-between items-center shadow-2xl z-50">
                <div className="flex items-center gap-6">
                    <BrainCircuitIcon className="w-8 h-8 text-[#b5892f]" />
                    <h2 className="text-2xl font-black text-[#efefef] uppercase italic tracking-tighter">Narrative Matrix: {initialData?.name || file?.name}</h2>
                </div>
                <div className="flex gap-4 relative">
                    <button 
                        onClick={() => setIsExportMenuOpen(!isExportMenuOpen)}
                        className="px-6 py-2 border border-[#6e501a] text-[#b5892f] text-[10px] font-black uppercase tracking-widest hover:bg-[#b5892f]/5 transition-all flex items-center gap-2"
                        disabled={isExporting}
                    >
                        {isExporting ? <SpinnerIcon className="w-3 h-3 animate-spin" /> : <DownloadIcon className="w-4 h-4" />}
                        {isExporting ? 'Capturing...' : 'Export Matrix'}
                        <ChevronDownIcon className={`w-3 h-3 transition-transform ${isExportMenuOpen ? 'rotate-180' : ''}`} />
                    </button>

                    {isExportMenuOpen && (
                        <div className="absolute top-full right-0 mt-2 w-48 bg-[#121212] border border-[#6e501a] shadow-2xl flex flex-col z-[100]">
                            <button onClick={handleExportPNG} className="p-4 text-left text-[10px] font-black text-[#efefef] uppercase tracking-widest hover:bg-[#b5892f] hover:text-black transition-all">Capture High-Res PNG</button>
