                className={`p-5 rounded-xl border transition-all active:scale-95 ${isSaved ? 'bg-blue-600 text-white border-blue-500 shadow-xl shadow-blue-500/30' : 'bg-slate-800 text-slate-400 border-slate-700 hover:text-white hover:bg-slate-700'}`}
              >
                {isSaved ? <BookmarkFilledIcon className="w-6 h-6" /> : <BookmarkIcon className="w-6 h-6" />}
              </button>
