    data: NarrativeMapResult; 
    onNodeClick: (node: NarrativeNode) => void; 
    activeNodeId: string | null; 
    svgRef: React.RefObject<SVGSVGElement | null>; 
    containerRef: React.RefObject<HTMLDivElement | null>; 
    filter: string;
