                                    </div>
                                </div>
                            ) : (
                                <div className="h-full flex items-center justify-center text-[#6e501a] text-[8px] lg:text-[10px] font-black uppercase tracking-widest italic opacity-20 text-center">Select node for deep evidence drill-down</div>
